import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function OtpVerify() {
  const [otp, setOtp] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const mobile = localStorage.getItem("mobile");

  useEffect(() => {
    if (!mobile) navigate("/");
  }, [mobile, navigate]);

  const handleVerify = async () => {
    if (!otp.trim()) {
      setMessage("Please enter OTP");
      return;
    }

    setLoading(true);
    setMessage("");

    try {
      const response = await axios.post(
        `http://localhost:8080/otp/verify?mobile=${mobile}&otp=${otp}`
      );
      setMessage(response.data);

      if (response.data.toLowerCase().includes("verified")) {
        setTimeout(() => navigate("/add-user"), 1200);
      }
    } catch (error) {
      setMessage("OTP verification failed. Try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5">
      <div className="card p-4 shadow-lg mx-auto" style={{ maxWidth: "450px" }}>
        <h2 className="text-center">OTP Verification</h2>
        <p className="text-muted text-center">Mobile: {mobile}</p>

        <input
          type="text"
          className="form-control mb-3"
          placeholder="Enter OTP"
          value={otp}
          onChange={(e) => setOtp(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleVerify()}
        />

        <button
          className="btn btn-success w-100 fw-bold"
          disabled={loading}
          onClick={handleVerify}
        >
          {loading ? "Verifying..." : "Verify OTP"}
        </button>

        {message && (
          <p
            className={`mt-3 fw-bold text-center ${
              message.toLowerCase().includes("verified")
                ? "text-success"
                : "text-danger"
            }`}
          >
            {message}
          </p>
        )}
      </div>
    </div>
  );
}
